from catalog_content import CATALOG,category,add

CATEGORY='fashion_history'
TRACKS=[
    {'id':'china','name':'中国女装沿革','scope':'汉代至1930年代；选取汉族女服及清代满族女服的代表样式'},
    {'id':'europe','name':'欧洲古典与近代女装','scope':'古希腊至1900年代；主要为欧洲城市、礼服与上层服装样式'},
    {'id':'modern','name':'20世纪至2010年代女装','scope':'主要为欧美都市时装与成衣；各时期可有多种并行风格'},
]
category(CATEGORY,'女装历史与演变','48项按三条时间线比较女装：从中国历代衣裙、欧洲古典与近代服装，到20世纪至2010年代都市时装。年代为代表性流行区间，观察腰线、袖型、裙体积、裙长与活动便利性的变化；同一时期的地域、身份和场景不同，服装并非单线替代。图例为据资料绘制的创作示意。',['R110','R114','R116','R117'])

def block(track,text):
    rows=[line.strip().split('|') for line in text.strip().splitlines()]
    assert len(rows)==16
    for order,(name,en,period,start,end,region,shape,change,recipe,refs) in enumerate(rows,1):
        add(CATEGORY,track['name'],f'{name}|{en}|{period} · {region}。{shape}。演变观察：{change}。')
        CATALOG[-1].update(added_in='38.0',fashion_history_reference=True,history_track=track['id'],history_order=order,
            history_period=period,history_start=int(start),history_end=int(end),history_region=region,
            history_silhouette=shape,history_change=change,history_recipe=recipe,
            history_reference_scope=track['scope'],adult_only=True,minor_reference=False,age_min=25,
            aliases=['女装历史','女装史','服装史','服装演变','女装演变',period,region],reference_ids=refs.split(','),
            note='这是选取代表轮廓的服装设计参考，图中人物为成年原创角色，配色与细节是资料基础上的示意推演，不是单件文物的精确复原。年代表示参考区间；地域、阶层、礼仪与日常场景会并存不同服饰，不能将一条时间线视为全体女性的统一着装。比较本项与同组相邻项的腰线、袖子、裙摆体积、开合及支撑结构，并通过相关阅读核对具体实物。')

